<?php
declare(strict_types=1);require_once __DIR__.'/includes/public-site.php';$context=public_site_fallback_context();try{$context=public_site_context(app_pdo());}catch(Throwable $e){error_log('Public locations load failed: '.$e->getMessage());}$settings=$context['settings'];$locations=$context['locations'];?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Locations | <?=app_escape((string)$settings['restaurant_name'])?></title><link rel="stylesheet" href="assets/css/site.css?v=20260914"></head><body><?php public_site_render_header($settings,'locations');?><main class="page-main"><section class="page-hero"><div class="shell"><div class="eyebrow">Locations</div><h1>Find Stonefellows.</h1><p>Active locations below come directly from the restaurant location records.</p></div></section><section class="section"><div class="shell"><?php if($locations):?><div class="location-grid"><?php foreach($locations as $location):$addr=public_site_format_address($location);?><article class="location-card"><div class="eyebrow">Location</div><h2><?=app_escape((string)$location['name'])?></h2><ul class="detail-list"><?php if($addr!==''):?><li><strong>Address</strong><br><?=app_escape($addr)?></li><?php endif;?><?php if(!empty($location['phone'])):?><li><strong>Phone</strong><br><a class="contact-link" href="tel:<?=app_escape(preg_replace('/[^+0-9]/','',(string)$location['phone'])??'')?>"><?=app_escape((string)$location['phone'])?></a></li><?php endif;?><?php if($settings['hours_text']!==''):?><li><strong>Hours</strong><br><?=nl2br(app_escape((string)$settings['hours_text']))?></li><?php endif;?></ul></article><?php endforeach;?></div><?php else:$fallback=public_site_format_address($settings);?><article class="location-card"><div class="eyebrow">Primary Location</div><h2><?=app_escape((string)$settings['restaurant_name'])?></h2><p><?=$fallback!==''?app_escape($fallback):'Location details have not been published yet.'?></p><?php if($settings['hours_text']!==''):?><p><?=nl2br(app_escape((string)$settings['hours_text']))?></p><?php endif;?></article><?php endif;?></div></section></main><?php public_site_render_footer($settings);?><script src="assets/js/site.js?v=20260914"></script></body></html>
